    private static let therapySearch = DirectorySource(name: "Gesundheitsportal · Psychotherapie nach Bundesland", url: "https://www.gesundheit.gv.at/service/beratungsstellen/gesund-leben/psyche-seele/psychotherapie-adressen.html")
    private static let psychology = DirectorySource(name: "Gesundheitsportal · Klinische Psychologie", url: "https://www.gesundheit.gv.at/gesundheitsleistungen/berufe/gesundheitsberufe-a-z/psychologische-berufe/klinische-psychologie.html")
    private static let crisisHelp = DirectorySource(name: "Gesundheitsportal · Krisenintervention", url: "https://www.gesundheit.gv.at/leben/psyche-seele/krisenintervention/krisenhilfe.html")
    private static let crisisNumbers = DirectorySource(name: "Gesundheitsportal · Krisen- und Notrufnummern", url: "https://www.gesundheit.gv.at/leben/suizidpraevention/anlaufstellen/notrufnummern.html")
    private static let schoolHelp = DirectorySource(name: "Gesundheitsportal · Schule und Psyche", url: "https://www.gesundheit.gv.at/service/beratungsstellen/gesund-leben/gesunde-lebenswelten/hilfe-bei-schulangst.html")
